@extends('layouts.app') @section('content')<h1>Cart</h1>@php($total=$cart->sum(fn($line)=>$line['price']*$line['quantity']))@forelse($cart as $line)<div class="card"><strong>{{ $line['name'] }}</strong> — KES {{ number_format($line['price'],2) }}<form method="post" action="{{ route('cart.update',$line['id']) }}">@csrf @method('PATCH')<input type="number" name="quantity" min="0" max="20" value="{{ $line['quantity'] }}"><button>Update</button></form></div>@empty<p>Your cart is empty.</p>@endforelse @if($cart->isNotEmpty())<h3>Total: KES {{ number_format($total,2) }}</h3>@auth<a href="{{ route('checkout.create') }}">Proceed to checkout</a>@else<a href="{{ route('login') }}">Log in to check out</a>@endauth@endif@endsection
